class Solution:
    def answerQueries(self, speeds: List[int], queries: List[int]) -> List[int]:
        a = speeds; out = []
        for d in queries:
            dq = deque(); best = None
            for i, x in enumerate(a):
                while dq and a[dq[-1]] <= x: dq.pop()
                dq.append(i)
                if dq[0] <= i - d: dq.popleft()
                if i >= d - 1: best = a[dq[0]] if best is None else min(best, a[dq[0]])
            out.append(best)
        return out

